import pandas as pd

GPT_MODEL = "gpt-4.1-2025-04-14"

# Metadata injected into every caption prompt (also the Molmo-7B prompt).
METADATA_PROMPT = 'It belongs to the genus **{genus}** (*{scientificName}*), part of the **{kingdom}** kingdom, **{phylum}** phylum, **{class}** class, **{order}** order, and **{family}** family. The species is **{species}** (*{specificEpithet}*). It grows on **{substrate}**. This fungi is **{poisonous}** (0 = non-poisonous, 1 = poisonous) and has an IUCN Red List status of **{iucnRedListCategory}**.'

METADATA_FIELDS = [
    "poisonous", "genus", "kingdom", "scientificName", "phylum", "specificEpithet",
    "species", "family", "order", "class", "iucnRedListCategory", "substrate",
]


def metadata_prompt(row: pd.Series) -> str:
    values = row[METADATA_FIELDS].fillna("unknown")
    values["poisonous"] = str(int(values["poisonous"]))
    return METADATA_PROMPT.format(**values.to_dict())


